export function Aside({
  heading = "{{heading}}",
  body = "{{body}}",
  side = "{{side}}",
  width = {{width}},
  accent = "{{accent}}",
}) {
  const isLeft = side === "left";
  return (
    <div style={{ display: "flex", flexDirection: isLeft ? "row-reverse" : "row", gap: 16, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", background: "#FAF7F2", padding: 16 }}>
      <article style={{ flex: 1, minWidth: 0 }}>
        <h4 style={{ margin: "0 0 8px", fontSize: 16 }}>Article</h4>
        <p style={{ margin: "0 0 8px", color: "#241430cc" }}>The primary content column keeps reading focus while a secondary area sits alongside it.</p>
        <p style={{ margin: 0, color: "#241430cc" }}>It carries context that supports the main text without interrupting it.</p>
      </article>
      <aside style={{ flex: "none", boxSizing: "border-box", width, borderLeft: isLeft ? "none" : `2px solid ${accent}`, borderRight: isLeft ? `2px solid ${accent}` : "none", padding: isLeft ? "4px 14px 4px 0" : "4px 0 4px 14px" }}>
        <h4 style={{ margin: "0 0 6px", fontSize: 13, textTransform: "uppercase", letterSpacing: ".04em", color: accent }}>{heading}</h4>
        <p style={{ margin: 0, fontSize: 13, color: "#241430cc" }}>{body}</p>
      </aside>
    </div>
  );
}
